  await page.fill('#full-name', '');
  await page.fill('#email-address', 'bad');
  await page.fill('#phone-number', 'abc');
  await page.click('button[type="submit"]');
  const activeId = await page.evaluate(() => document.activeElement && document.activeElement.id);
  const errors = await page.evaluate(() => ({
    name: document.getElementById('full-name-error').textContent,
    email: document.getElementById('email-error').textContent,
    phone: document.getElementById('phone-error').textContent,
    status: document.getElementById('form-status').textContent
  }));
  console.log(JSON.stringify({ activeId, errors }));
  await browser.close();
  process.exit(wcag.length ? 1 : 0);
})();
