   <a class="skip-link" href="#support-form">Skip to support form</a>
   <main id="main-content">
     <div class="page-shell">
       <section class="panel" aria-labelledby="form-heading">
         <h1 id="form-heading">Contact support</h1>
         <p class="intro">Send us your details and we'll get back to you as soon as possible.</p>
         <p class="legend-note">Fields marked with <span class="required-mark" aria-hidden="true">*</span> are required.</p>

         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
             <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error">
             <p class="error-text" id="full-name-error" aria-live="polite"></p>
           </div>

           <div class="form-field">
             <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
             <input id="email-address" name="emailAddress" type="email" autocomplete="email" required aria-describedby="email-help email-error">
             <p class="help-text" id="email-help">We will use this to reply to your request.</p>
             <p class="error-text" id="email-error" aria-live="polite"></p>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number</label>
             <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-help phone-error">
             <p class="help-text" id="phone-help">Optional. Use a format like +1 555 123 4567 or (555) 123-4567.</p>
             <p class="error-text" id="phone-error" aria-live="polite"></p>
           </div>

           <div class="actions">
             <button type="submit">Send message</button>
             <p class="note">Required fields are validated before the form is accepted.</p>
           </div>

           <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
         </form>
       </section>
     </div>
   </main>

   <script>
     (() => {
       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");
       const fields = {
         fullName: {
           input: document.getElementById("full-name"),
           error: document.getElementById("full-name-error"),
           validator: (value) => value.trim() ? "" : "Error: Enter your full name."
         },
         emailAddress: {
           input: document.getElementById("email-address"),
           error: document.getElementById("email-error"),
           validator: (value) => {
             if (!value.trim()) {
               return "Error: Enter your email address.";
             }

             return fields.emailAddress.input.validity.typeMismatch || !fields.emailAddress.input.checkValidity()
               ? "Error: Enter a valid email address like name@example.com."
               : "";
           }
         },
         phoneNumber: {
           input: document.getElementById("phone-number"),
           error: document.getElementById("phone-error"),
           validator: (value) => {
             const trimmed = value.trim();
             if (!trimmed) {
               return "";
             }

             const phonePattern = /^[+()0-9\s.-]{7,}$/;
             return phonePattern.test(trimmed)
               ? ""
               : "Error: Enter a phone number using digits, spaces, parentheses, dashes, or a leading +.";
           }
         }
       };

       const setFieldState = (field, message) => {
         field.error.textContent = message;
         field.input.setAttribute("aria-invalid", message ? "true" : "false");
       };

       const validateField = (field) => {
         const message = field.validator(field.input.value);
         setFieldState(field, message);
         return !message;
       };

       Object.values(fields).forEach((field) => {
         field.input.addEventListener("input", () => {
           if (field.error.textContent) {
             validateField(field);
           }
           status.textContent = "";
           status.removeAttribute("data-state");
         });

         field.input.addEventListener("blur", () => {
           validateField(field);
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const validity = Object.values(fields).map(validateField);
         const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute("aria-invalid") === "true");

         if (validity.every(Boolean)) {
           status.textContent = "Thanks — your message is ready to send.";
           status.dataset.state = "success";
           return;
         }

         status.textContent = "Please fix the highlighted fields.";
         status.removeAttribute("data-state");
         firstInvalid?.input.focus();
       });
     })();
   </script>
 </body>
 </html>

